import{_ as o,o as n,c as a,a3 as t}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Tianshi Academy and Chishi Academy of Sciences Online Documentation","description":"","frontmatter":{"translationSource":{"title":"天师府学院及赤石科学院在线文档","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0AubHTBziqsGYU4dRT3JPz","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/tianshi-academy-and-chishi-academy-of-sciences-online-documentation"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/tianshi-academy-and-chishi-academy-of-sciences-online-documentation"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/tianshi-academy-and-chishi-academy-of-sciences-online-documentation"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/tianshi-academy-and-chishi-academy-of-sciences-online-documentation"}]]},"headers":[],"relativePath":"tianshi-academy-and-chishi-academy-of-sciences-online-documentation.md","filePath":"logistics/src/page-0AubHTBziqsGYU4dRT3JPz.md"}'),i={name:"tianshi-academy-and-chishi-academy-of-sciences-online-documentation.md"};function r(s,e,d,l,p,c){return n(),a("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><h1 id="tianshi-academy-and-chishi-academy-of-sciences-online-documentation" tabindex="-1">Tianshi Academy and Chishi Academy of Sciences Online Documentation <a class="header-anchor" href="#tianshi-academy-and-chishi-academy-of-sciences-online-documentation" aria-label="Permalink to &quot;Tianshi Academy and Chishi Academy of Sciences Online Documentation&quot;">​</a></h1><blockquote><p>Source page ID: <code>0AubHTBziqsGYU4dRT3JPz</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0AubHTBziqsGYU4dRT3JPz" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><div class="callout"><p><span id="source-block-PhVKN4HxE51DF26JIafk15"></span></p><h4 id="pinned" tabindex="-1">Pinned <a class="header-anchor" href="#pinned" aria-label="Permalink to &quot;Pinned&quot;">​</a></h4><p>This public collaborative documentation project for Arknights: Endfield AIC players records the vast majority of AIC research achievements and our current tasks, promoting the spread and diversity of AIC gameplay. We currently lack contributors and invite AIC researchers to help write it.</p><p><a href="/endfield-skydoc/task-board-rules">Task Board Agreement</a></p><p><a href="/endfield-skydoc/related-links">Related Links</a></p><p><a href="/endfield-skydoc/signpost-board">Signpost Board</a></p><p>Discussion groups: 877646091 (Talos-II Hongshan Chishi Academy of Sciences, <span class="mark-red">no blueprint troubleshooting</span>); 1124883952 (Talos-II Tianshi Academy C, full); 483200086 (Talos-II Tianshi Academy B, full); 1095487306 (Talos-II Tianshi Academy A, full); 1032818662 (Talos-II Tianshi Academy D).</p><p><span class="mark-red">Non-editing readers can send suggestions </span><a href="https://docs.qq.com/form/page/DTkJYbk16aGZyaEFD" target="_blank" rel="noreferrer"><span class="mark-blue">here</span></a><span class="mark-red">.</span></p><p><span class="mark-rose_red">This collection contains more than one blueprint. If you need a particular blueprint, please look for it yourself. Public blueprints that receive many questions usually have their locations listed on the </span><span class="mark-red">Signpost Board</span><span class="mark-rose_red">.</span></p></div><p><span id="source-block-WDYYSqySBbIlgRgSYk8dYO"></span></p><h3 id="knowledge-base" tabindex="-1">Knowledge Base <a class="header-anchor" href="#knowledge-base" aria-label="Permalink to &quot;Knowledge Base&quot;">​</a></h3><p>Refined AIC findings are summarized and archived in the knowledge base for casual players.</p><p><a href="/endfield-skydoc/basic-factory-principles">Basic AIC Principles</a></p><p><a href="/endfield-skydoc/logistics-principles-and-frontier-research">Logistics Principles and Some Terms</a></p><p><a href="/endfield-skydoc/logistics-structures-with-special-effects">Logistics Structures with Special Effects</a></p><p><a href="/endfield-skydoc/new-player-progression-and-precautions-wuling">Newcomer Progression and Precautions: Wuling</a></p><p><a href="/endfield-skydoc/production-control-and-frontier-research">Production Control and Frontier Research</a></p><p><a href="/endfield-skydoc/blueprint-compression-and-production-line-design-results">Blueprint Compression and Production-Line Design Results</a></p><p><a href="/endfield-skydoc/code-link-library">Code Link Library</a></p><p><span id="source-block-9vfK2fG3iZciHEfReOAJVQ"></span></p><h3 id="task-board" tabindex="-1">Task Board <a class="header-anchor" href="#task-board" aria-label="Permalink to &quot;Task Board&quot;">​</a></h3><p><span id="source-block-4mqQ0otk3LNRXEw5RTkVOC"></span></p><h4 id="tasks-currently-underway-under-discussion" tabindex="-1">Tasks Currently Underway / Under Discussion <a class="header-anchor" href="#tasks-currently-underway-under-discussion" aria-label="Permalink to &quot;Tasks Currently Underway / Under Discussion&quot;">​</a></h4><p>Please do not create subpages here. Embedded page references are discouraged; hyperlinks may be used here.</p><p><a href="/endfield-skydoc/teaching-the-basics-of-adaptive-aic">Teaching the Basics of Adaptive AIC</a></p><p><a href="/endfield-skydoc/small-modules-with-zero-activator-waste#source-block-41WZUHyiBsCQiGi7LmD3jq">Small Module with Zero Activation-Material Waste</a></p><p><a href="/endfield-skydoc/feedforward-without-priority">Feedforward without Priority?</a></p><p>Automatic Pyrrolite/Hetonite/Heavy Xiranite switching, possibly meaning 5 cores of lower-priority Heavy Xiranite.</p><p><a href="/endfield-skydoc/how-endfield-displays-production-reports">How Endfield Displays Production Reports</a></p><p><span id="source-block-fECpEEu4gjllx72RUkDXZV"></span></p><h4 id="long-term-extremely-long-tasks" tabindex="-1">Long-Term: Extremely Long Tasks <a class="header-anchor" href="#long-term-extremely-long-tasks" aria-label="Permalink to &quot;Long-Term: Extremely Long Tasks&quot;">​</a></h4><p><a href="/endfield-skydoc/abnormal-logistics-phenomena-and-hypotheses-about-underlying-logic">Abnormal Logistics Phenomena and Hypotheses about Underlying Logic</a> · <a href="/endfield-skydoc/network-flow-theory-for-blocking-round-robin-inputs-and-outputs">Network Flow Theory for Blocking / Round-Robin Inputs and Outputs</a> · <a href="/endfield-skydoc/factory-production-plans-logic-and-layout-implementation-across-versions">AIC Production Plans, Logic and Layout Implementation across Versions</a></p><p><span id="source-block-FKHdkGDroXSpWzjbPnaLLJ"></span></p><h4 id="research-data-collection-and-theoretical-investigation" tabindex="-1">Research: Data Collection and Theoretical Investigation <a class="header-anchor" href="#research-data-collection-and-theoretical-investigation" aria-label="Permalink to &quot;Research: Data Collection and Theoretical Investigation&quot;">​</a></h4><p><a href="/endfield-skydoc/research-into-production-line-design-theory">Research into Production-Line Design Theory</a> · <a href="/endfield-skydoc/feedforward-without-priority">Feedforward without Priority?</a> · <a href="/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings">Research into Yuanyuan Manor Tips and Theme Revenue</a> · <a href="/endfield-skydoc/the-most-useless-thing-in-endfield">The Most Useless Thing in Endfield?</a></p><p>Investigating clue acquisition patterns in the Reception Room.</p><p>Minimizing Protocol capacity use without considering footprint.</p><p><span id="source-block-HpbSDTPFs5LguzxYgD8p6R"></span></p><h4 id="engineering-code-simulation-and-practical-construction" tabindex="-1">Engineering: Code Simulation and Practical Construction <a class="header-anchor" href="#engineering-code-simulation-and-practical-construction" aria-label="Permalink to &quot;Engineering: Code Simulation and Practical Construction&quot;">​</a></h4><p><a href="/endfield-skydoc/developing-tools-and-algorithms-for-production-line-compression">Developing Production-Line Compression Tools and Algorithms</a> · <a href="/endfield-skydoc/modified-quantitative-calculator">Modified Quantitative Calculator</a> · <a href="/endfield-skydoc/perfect-endfield-industrial-simulation-code">Perfect Endfield Industrial Simulation Code</a> · <a href="/endfield-skydoc/optimizing-the-reactor-crucible-trash-can">Optimizing the Reaction-Tank Trash Can</a> · <a href="/endfield-skydoc/improving-the-xircon-module">Improving the Xircon Module</a> · <a href="/endfield-skydoc/automatic-switching-for-reactions-with-multiple-raw-materials">Automatic Switching for Reactions with Multiple Inputs</a> · <a href="/endfield-skydoc/small-modules-with-zero-activator-waste">Small Module with Zero Activation-Material Waste</a></p><p><span id="source-block-SzpRJ9dDbu8PlSGxaILkTg"></span></p><h4 id="synthesis-video-production-and-long-term-content" tabindex="-1">Synthesis: Video Production and Long-Term Content <a class="header-anchor" href="#synthesis-video-production-and-long-term-content" aria-label="Permalink to &quot;Synthesis: Video Production and Long-Term Content&quot;">​</a></h4><p><a href="/endfield-skydoc/yuanyuan-manor-assistant">Yuanyuan Manor Assistant</a> · <a href="/endfield-skydoc/making-videos-of-group-members-results">Videos of Group Members&#39; Results</a> · <a href="/endfield-skydoc/regional-placement-limits">Regional Placement Limits</a> · <a href="/endfield-skydoc/unifying-terminology-and-building-a-dictionary">Standardizing Terminology and Making a Dictionary</a> · <a href="/endfield-skydoc/building-the-task-board">Task Board Development</a></p><p>Develop <a href="http://github.com/hongshan-academy/discussion/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</p><p><a href="/endfield-skydoc/applications-of-some-theories">Applications of Various Theories</a> · <a href="/endfield-skydoc/issues-with-publishing-results">Issues with Publishing Results</a> · <a href="/endfield-skydoc/establishing-a-customer-support-department">Establishing an After-Sales (Volunteer Troubleshooting) Department</a> · <a href="/endfield-skydoc/repository-of-survey-suggestions">Repository of Survey Suggestions</a></p><p><span id="source-block-1ivGcAdJkX3Mqyh6RPR5Gq"></span></p><h4 id="group-members-results—task-board" tabindex="-1">Group Members&#39; Results—Task Board <a class="header-anchor" href="#group-members-results—task-board" aria-label="Permalink to &quot;Group Members&#39; Results—Task Board&quot;">​</a></h4><p>Collect temporary reusable findings during research in a more modular, node-based manner.</p><p>This section should gradually be retired and merged into the knowledge base.</p><p><a href="/endfield-skydoc/input-output-merge-priority-theory">Input / Output / Merge Priority Theory: A Brief Explanation</a></p><p><a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a></p><p><a href="/endfield-skydoc/uniform-binary">Uniform Binary Output</a> · <a href="/endfield-skydoc/perfectly-uniform-rational-output">Perfectly Uniform Rational-Rate Output</a> · <a href="/endfield-skydoc/price-patterns-of-variable-goods-groups">Floating Goods-Group Pricing Patterns</a> · <a href="/endfield-skydoc/binary-flow-stabilizer">Binary Flow Stabilizer</a> · <a href="/endfield-skydoc/explaining-predicting-and-applying-the-4n-1s-stall">Explaining, Predicting and Applying the 4n, 1s Stall (Output Lag)</a> · <a href="/endfield-skydoc/credit-shop-stock">Credit Store Stock</a> · <a href="/endfield-skydoc/constructing-production-line-node-components">Constructing Production-Line Node Components</a> · <a href="/endfield-skydoc/t-flip-flop">T Flip-Flop</a> · <a href="/endfield-skydoc/yazhen-buckflower-release-machine">Yazhen/Buckflower Release Machine</a></p><p><a href="/endfield-skydoc/flow-theory-for-idealized-logistics-systems">Flow Theory for Idealized Systems</a></p><p><a href="/endfield-skydoc/controlling-the-share-of-pingtubers-sent-to-starch-with-the-number-of">Using Pingtuber Leaf Counts to Control the Proportion of Pingtubers Used for Starch</a> · <a href="/endfield-skydoc/logistics-systems-with-strictly-uniform-rational-output">Logistics Systems with Strictly Uniform Rational Output</a> · <a href="/endfield-skydoc/theory-of-perfectly-uniform-rational-output-devices">Theory of Perfectly Uniform Rational-Rate Output Devices</a></p><p><span id="source-block-4zlsSafirl7EQiDCeti7sz"></span></p><h4 id="other-collapsed-pages" tabindex="-1">Other Collapsed Pages <a class="header-anchor" href="#other-collapsed-pages" aria-label="Permalink to &quot;Other Collapsed Pages&quot;">​</a></h4><p><a href="/endfield-skydoc/finished-abandoned">Finished / Abandoned</a> · <a href="/endfield-skydoc/some-theories-and-proofs">Theories and Proofs</a></p><p><span id="source-block-0N0AqcNFNWPd9qBD5PgumP"></span></p><h4 id="task-board-update-announcements" tabindex="-1">Task Board Update Announcements <a class="header-anchor" href="#task-board-update-announcements" aria-label="Permalink to &quot;Task Board Update Announcements&quot;">​</a></h4><p><strong>2026/10/27</strong></p><p>The baseline is abnormal; routine maintenance has been abandoned.</p><p><strong>2026/10/26</strong></p><p>Added “Task Board ARG?”</p><p>Added “Xiragen\\Acridgen Serial,” covering a mixed Fluid-Gas Transmuting Unit setup provided by 断懒.</p><p>Added many definitions to “Logistics Principles and Some Terms.”</p><p>Added four kinds of qualifiers to “Reference for Common Production-Line Concepts.”</p><p>Tidied up the descriptions in “Depot-Related Priority Phenomena.”</p><p>Added “How Do Humans Lay Things Out?” to “Compression Algorithms for Implementing Idealized Systems,” providing plenty of algorithm ideas.</p><p>Added supplementary notes on the description to “Conventional Priority Architectures (Not Structures).”</p><p>Added the graduated Xiragen output for various cases to the “Sanctuary of Ink” Version.</p><p>Added several markers to “1.6 Full-Storage Oscillation Plan”; no content updates.</p><p>Cleaned up useless content in “Basic AIC Principles.”</p><p><strong>2026/10/25</strong></p><p>Added “Common / Frequently Used Tags” to “Blueprint Compression and Production-Line Design Results.”</p><p>Added an “acceptance logic” checklist to “Research on Pipe Transport Rules.”</p><p>Added one possible explanation to The “4 Items, 1s Stall” Output Issue When Switching Multi-Input Recipes.</p><p>Added two possible explanations to “Changes Caused by Going Offline.”</p><details><summary>“Newcomer Progression and Precautions: Wuling” has many changes, mostly new tips</summary><p>The blueprints are marked as incremental blueprints</p><p>Mineral requirements are made explicit</p><p>Base expansion area requirements are made explicit</p><p>Final output and one-time output are labeled</p><p>Tips on connecting Inergen and water</p></details><p>Added some operational details and annotations to “1.5 Automatic Maximum Gross Production.”</p><p>Added substantial content to “1.6 Full-Storage Oscillation Plan”; see the page for details.</p><p>Added direct link text to “Related Links” in case Tencent Docs acts up and cannot open web pages.</p><p>Added notes on staffing and communication to “Establishing an After-Sales (Volunteer Troubleshooting) Department.”</p><p>Updated “i葱TV” in “ko鸟&#39;s Workshop.”</p><p>Added acknowledgements to “Automatic Switching for Reactions with Multiple Inputs.”</p><p><strong>2026/10/24</strong></p><p>Added “Theory of Actual Physical Laws.”</p><p>Added a flow-limiter definition to “Logistics Principles and Some Terms.”</p><p>Added the effects of stacked Sprinklers to “Planting and Automatic-Harvester Mechanics: Research and Applications.”</p><p>Added content on “the side-priority phenomenon when a Depot Unloader connects to a reaction tank&#39;s Converger” to “Introduction to Analyzing Endfield Logistics Bugs.”</p><p>Added daily records and i葱TV to “ko鸟&#39;s Workshop,” and removed content about technical exchange on external networks.</p><p>Added maintenance notes for the English task board to “Related Links.”</p><p>Added total mineral data and development tips to the “Sanctuary of Ink” Version.</p><p>Added 代办&#39;s blueprint code to “1.6 Full-Storage Oscillation Plan.”</p><p>Imported a chat log into “Teaching the Basics of Adaptive AIC” to show that work on it is progressing.</p><p>Added a link to “Newcomer Progression and Precautions: Wuling” on the Signpost Board.</p><p>Added “Group Members&#39; Front-End Reference” and an open-source blog front-end link to “Code Link Library.”</p><p>Added two people to “Establishing an After-Sales (Volunteer Troubleshooting) Department”: 凯尔希思衡托 and SSnighter.</p><p>Added image captions to “Small Module with Zero Activation-Material Waste.”</p><p><strong>2026/10/23</strong></p><p>Created “Separator-Core Module,” storing 君&#39;s 18*18 separator-core module.</p><p>Created “Small Module with Zero Activation-Material Waste,” storing Hetonite block-to-liquid conversion (feedforward and feedback) + a single-tank dual-core Heavy Xiranite module<br> Created “AI Excerpts_Website Content Collection” as a summary of the chat logs about JMY&#39;s website development; the details should be organized later.</p><details><summary>“Conventional Priority Architectures (Not Structures)” has many changes; the classification framework was revised overall</summary><p>Added the section heading “Conventional Priorities,” with a related explanation<br> Added the section headings “Special Priority Relationships” and “Input–Product Priority Relationships,” at the same level as the former;<br> “Product Empty-Storage Oscillation” and “Input Empty-Storage Oscillation” were moved and reclassified;<br> Removed the link <a href="./">Smart Restocking and Ingredient-Preparation Production Line</a>.</p></details><p>Added a qualifier reference to “Reference for Common Production-Line Concepts.”</p><p>Added a “production-line evaluation” step section to “Research into Production-Line Design Theory.”</p><p>Added a new conclusion about offline slowdown to “Changes Caused by Going Offline.”</p><p>Made some supplementary notes in “Improving the Xircon Module.”</p><p>Added discussion of the separator core to “Dreamscape of Wind and Snow” Version / Explanation: Self-Balancing Production Lines and Adaptive Devices.</p><p>Supplemented the full-storage oscillation structure description and initialization in “Sanctuary of Ink” Version / 1.6 Full-Storage Oscillation Plan.</p><p><strong>2026/10/22</strong></p><p>Created “Automatic Switching for Reactions with Multiple Inputs.”</p><p>Renamed “Hongshan Academy Smart Network Development” to “JMY&#39;s Website Development.”</p><p>Removed “A Compact Line Automatically Switching between SC and LC Batteries” from tasks currently underway.</p><p>Added input empty-storage oscillation to Conventional Priority Architectures.</p><p>Added the manifold–Converger priority “input-phase problem” and the recipe representation for two parallel Purification–Solid-Gas groups to Some Simpler Adaptive Setups, and marked one blueprint code as needing maintenance.</p><p>Added NH (D-15191) to Establishing an After-Sales (Volunteer Troubleshooting) Department.</p><p>Another 53 pages had reading errors; the baseline may need to be rebuilt later.</p><p><strong>2026/10/21</strong></p><p>Incremental change checking failed. Rebuilt the baseline.</p><p><strong>2026/10/20</strong></p><p>This section is gradually being brought back into use. Updates will no longer be live; AI will compare the documents from consecutive days, with updates posted each evening.</p><p>Many changes were consolidated today, so no detailed announcement will be made. This section will mainly record smaller incremental changes afterward.</p><p><strong>2026/9/10</strong></p><p>Since main-page update announcements cannot show internal content changes, maintenance of this module will gradually cease.</p><p><strong>2026/8/29</strong></p><p>Uploaded Introduction to Analyzing Endfield Logistics Bugs and marked several documents outdated.</p><p><strong>2026/8/26</strong></p><p>Added the synthesis task Endfield Event Data Statistics, hoping it will be findable when event data is needed later.</p><p><strong>2026/8/24</strong></p><p>Added Pinned, including the Task Board Agreement.</p><p>Added Knowledge Base, including archived content.</p><p><strong>2026/8/21</strong></p><p>Added the engineering task Quantitative Calculator Improvements and Implementation for calculator optimization needs.</p><p><strong>2026/8/20</strong></p><p>Reposted Proof of Flow-Rate Uniqueness for Flow Limiters from group chat to Theories and Proofs.</p><p><strong>2026/8/15</strong></p><p>Removed A Descriptive Language for Rate Control in All Splitting/Merging Structures because it largely overlaps Blocking-Flow Research.</p><p>Renamed Videos of Blocking-Flow/Range-Related Content to Videos of Group Members&#39; Results for broader applicability.</p><p>Added Results from Outside the Group, hoping to present non-members&#39; work with annotations to facilitate dissemination.</p><p>Since droplet loss apparently no longer occurs, renamed Pipe Transmission Rules, Droplet Loss, and Abnormal Pipe Slowdown Research to Pipe Transmission Rules Research.</p><p>Created Abnormal Logistics Phenomena and Hypotheses about Underlying Logic, merging related research tasks.</p><p>Marked Overflow in Controlled Oscillating Generation with Battery Sequences of Specified Uniformity complete because Calculating Stored-Energy Range provides the proof and theory.</p><p>Moved Clock-Signal-Based Single-Forge Heavy Xiranite into Rational-Rate Forge of the Sky or Single-Forge Heavy Xiranite Production due to duplication.</p><p>Moved the synthesis task General Splitter Theory into the research task Blocking-Flow Research due to duplication.</p><p>Renamed New-Version AIC Research to AIC Production Plans, Logic, and Layout Implementation across Versions to avoid ambiguity.</p><p>Renamed Blocking-Flow-Related Theory to Blocking | Round-Robin Input/Output Flow Theory for broader applicability.</p><p><strong>2026/8/13</strong></p><p>Moved Credit Store Stock Research to completed, since its video was published long ago.</p><p><strong>2026/7/29</strong></p><p>Added the engineering task Clock-Signal-Based Single-Forge Heavy Xiranite, based on results brought by kokobird.</p><p><strong>2026/7/7</strong></p><p>Resumed task-board maintenance and removed What Happened Today.</p><p>Removed the research task Equivalence of Two Beatty-1 Definitions due to duplication; see its namesake subpage under Theories and Proofs.</p><p>Removed Variable-Blocking Rational-Rate Limiter Theory because it overlaps blocking-flow theory.</p><p>Removed Choosing PPT-Like Video-Making Software after a long period without responses.</p><p>Moved Reactor Crucible Properties Research and Organization from synthesis to research.</p><p>Added New-Version AIC Research, combining previous and future version-start tasks.</p><p>Marked Proof of Minimum Installed Power for Binary-Flow-Stabilizer Power Control complete, pending extraction of results into Group Members&#39; Results.</p><p>Removed Leap-Year Rule Theory and Video Script because it duplicates Organizing and Textbook-Style Presentation of Perfectly Uniform Rational-Rate Output Theory.</p><p><strong>2026/5/24</strong></p><p>With the preview video released, version 1.2 is considered nearly over; marked Version 1.2 Production Plans and Blueprint Design finished.</p><p><strong>2026/5/16</strong></p><p>Renamed Pipe Transmission Rules and Droplet-Loss Research to Pipe Transmission Rules, Droplet Loss, and Abnormal Pipe Slowdown Research after noticing a new phenomenon.</p><p><strong>2026/5/10</strong></p><p>Created Group Members&#39; Results to record all findings atomically, including flashes of inspiration, for later reference and thought.</p><p>Because the task board&#39;s structure has inconveniences, prepare a restructuring to serve research better.</p><p><strong>2026/5/7</strong></p><p>Renamed Splitter Output Lag Research to Output Lag Research after reproducing it without Splitters, retaining the “4n, half-tile stall” tag for discoverability.</p><p><strong>2026/5/4</strong></p><p>Marked dispatch-material pricing topics complete because the video was published.</p><p>Officially discontinued What Happened Today due to poor maintenance, lack of readers, etc.</p><p>Renamed Delay with Directly Connected Convergers/Splitters to Terminal-Stash Placement Order Affecting Priority in Priority-Merging Structures, matching the actual research more closely.</p><p><strong>2026/4/20</strong></p><p>Marked Practical Feasibility of Mixed Reactor Crucible Use completed–abandoned; it should merge into version-start tasks.</p><p><strong>2026/4/18</strong></p><p>Added Currently Underway / Under Discussion to identify which tasks the group is discussing.</p><p><strong>2026/4/17</strong></p><p>Changed Version 1.2 Advance Preparation to Version 1.2 Preparation because the update arrived.</p><p><strong>2026/4/11</strong></p><p>Added Version 1.2 Advance Preparation after the version 1.2 preview.</p><p>Deleted Converger Priority on Loops because it merged into Delay with Directly Connected Convergers/Splitters; Converger priority, damping, and logistics micro-delays are currently also thought to arise from that phenomenon.</p><p>Added Theories and Proofs to collect detailed reusable proofs.</p><p><strong>2026/4/7</strong></p><p>Added Delay with Directly Connected Convergers/Splitters.</p><p><strong>2026/4/6</strong></p><p>Added Overflow in Controlled Oscillating Generation with Battery Sequences of Specified Uniformity, a subtask derived from Proof of Minimum Installed Power for Binary-Flow-Stabilizer Power Control.</p><p><strong>2026/4/1</strong></p><p>Marked The Mysterious Constant 11.8/h completed–abandoned because most related problems were fixed.</p><p>Marked Version 1.1 Preparation complete because considerable time had passed since the update.</p><p><strong>2026/3/30</strong></p><p>Marked Offline Slowdown and Possible Remedies completed–fixed.</p><p><strong>2026/3/27</strong></p><p>Marked Logistics Micro-Delay complete.</p><p><strong>2026/3/22</strong></p><p>Marked Reactor Crucible Liquid Disappearance completed–fixed.</p><p><strong>2026/3/21</strong></p><p>Added What Happened Today, using AI summaries of group chat to facilitate looking up a particular day&#39;s discussion.</p><p><strong>2026/3/20</strong></p><p>Added The Mysterious Constant 11.8/h, Proof of Minimum Installed Power for Binary-Flow-Stabilizer Power Control, and Reactor Crucible Liquid Disappearance.</p><p><strong>2026/3/16</strong></p><p>Added droplet-loss research to pipe transmission rules.</p><p><strong>2026/3/13</strong></p><p>Marked mixed Reactor Crucible use as low feasibility.</p><p>Linked the dispatch-material pricing video script.</p><p><strong>2026/3/12</strong></p><p>Converted the task board to an online document.</p><p>Added Task Board Development.</p><p>Added the personal task Version 1.1 Preparation.</p><p>/</p></div>',1)])])}const g=o(i,[["render",r]]);export{h as __pageData,g as default};
